PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL);
INSERT OR IGNORE INTO users VALUES('a','Demo A'),('b','Demo B');
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,recovery_hash TEXT NOT NULL,last_active INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS rooms_activity ON rooms(last_active);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,actor_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES users(id),client_id TEXT NOT NULL,request_hash TEXT NOT NULL,text TEXT NOT NULL,reply_to TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,edited_at INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0,delivered INTEGER NOT NULL DEFAULT 0,read INTEGER NOT NULL DEFAULT 0,UNIQUE(room_id,sender_id,client_id));
CREATE INDEX IF NOT EXISTS messages_history ON messages(room_id,created_at,id);
CREATE TABLE IF NOT EXISTS preferences(room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,actor_id TEXT NOT NULL REFERENCES users(id),message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,starred INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(room_id,actor_id,message_id));
CREATE TABLE IF NOT EXISTS pins(room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,PRIMARY KEY(room_id,message_id));
